20	// Helper function to extract user and shortcut ID from shortcut resource name.
21	// Format: users/{user}/shortcuts/{shortcut}.
22	func (s *APIV1Service) extractUserAndShortcutIDFromName(ctx context.Context, name string) (*store.User, string, error) {
23		parts := strings.Split(name, "/")
24		if len(parts) != 4 || parts[0] != "users" || parts[2] != "shortcuts" {
25			return nil, "", errors.Errorf("invalid shortcut name format: %s", name)
26		}
27	
28		user, err := ResolveUserByName(ctx, s.Store, BuildUserName(parts[1]))
29		if err != nil {
30			return nil, "", err
31		}
32		if user == nil {
33			return nil, "", errors.Errorf("user not found: %s", parts[1])
34		}
35	
36		shortcutID := parts[3]
37		if shortcutID == "" {
38			return nil, "", errors.Errorf("empty shortcut ID in name: %s", name)
39		}
40	
41		return user, shortcutID, nil
42	}
